package org.sleepwell.app;
import android.content.SharedPreferences;
import org.json.*;
import java.util.*;

/** Strict cue preferences and per-run compare-and-save journal. Reading never arms output. */
final class TravelCueStore {
 static final String CONFIG="travelCues",RUN="travelCueRun";
 final SharedPreferences preferences;TravelCueStore(SharedPreferences p){preferences=p;}
 TravelCuePlan load(TravelPlan trip,long now){String raw=preferences.getString(CONFIG,"");if(raw.isEmpty())return TravelCuePlan.defaults(trip,now);try{return TravelCueJson.decode(new JSONObject(raw));}catch(Exception failure){throw new IllegalStateException("Light-cue settings could not be read. Existing data was kept.",failure);}}
 TravelCueSession.State last(){String raw=preferences.getString(RUN,"");if(raw.isEmpty())return null;try{JSONObject j=new JSONObject(raw);Set<String> fields=Set.of("version","nonce","phase","start","end","requests","skipped","message");if(j.length()!=fields.size())throw new JSONException("Invalid status fields");for(Iterator<String> it=j.keys();it.hasNext();)if(!fields.contains(it.next()))throw new JSONException("Unknown status field");if(TravelCueJson.integer(j,"version")!=1)throw new JSONException("Invalid version");String nonce=TravelCueJson.text(j,"nonce");if(!UUID.fromString(nonce).toString().equals(nonce))throw new JSONException("Invalid identity");long start=TravelCueJson.integer(j,"start"),end=TravelCueJson.integer(j,"end");int requests=Math.toIntExact(TravelCueJson.integer(j,"requests")),skipped=Math.toIntExact(TravelCueJson.integer(j,"skipped"));String message=TravelCueJson.text(j,"message");TravelCueSession.Phase phase=TravelCueSession.Phase.valueOf(TravelCueJson.text(j,"phase"));boolean failedBeforeWindow=phase==TravelCueSession.Phase.ERROR&&start==0&&end==0&&requests==0&&skipped==0;if((!failedBeforeWindow&&(start<=0||end<=start||end-start>3600000L))||requests<0||requests>240||skipped<0||skipped>240||message.length()>240)throw new JSONException("Invalid status");return new TravelCueSession.State(nonce,phase,start,end,requests,skipped,message);}catch(Exception failure){throw new IllegalStateException("The last cue status is unavailable. No cue session was restarted.",failure);}}
 void begin(String nonce,long revision){synchronized(TravelPlans.LOCK){TravelCueSession.State old=last();if(old!=null&&old.busy()&&TravelCues.control.live(old.nonce))throw new IllegalStateException("A cue session is already running.");commit(preferences.edit().putString("travelCueOwner",nonce).putLong("travelCueOwnerRevision",revision));}}
 void save(TravelCueSession.State state,long revision){synchronized(TravelPlans.LOCK){if(!state.nonce.equals(preferences.getString("travelCueOwner",""))||preferences.getLong("travelCueOwnerRevision",-1)!=revision)throw new IllegalStateException("The cue session changed.");try{JSONObject j=new JSONObject().put("version",1).put("nonce",state.nonce).put("phase",state.phase.name()).put("start",state.start).put("end",state.end).put("requests",state.requests).put("skipped",state.skipped).put("message",state.message);commit(preferences.edit().putString(RUN,j.toString()));}catch(JSONException impossible){throw new IllegalStateException(impossible);}}}
 static void commit(SharedPreferences.Editor edit){if(!edit.commit())throw new IllegalStateException("Light-cue settings could not be saved.");}
}
